package com.coraline.feast;

import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.gametest.*;

@GameTestHolder("coraline") @PrefixGameTestTemplate(false)
public final class RescueKeyMigrationGameTests {
    private static ServerPlayer player(GameTestHelper helper){var level=helper.getLevel();var p=new ServerPlayer(level.getServer(),level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"KeyMigrationQA"));p.connection=new net.minecraft.server.network.ServerGamePacketListenerImpl(p.server,new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p);var s=new VisitData.Scene();s.owner=p.getUUID();s.door=java.util.UUID.randomUUID();VisitData.get(p.server).scenes.put(s.owner,s);var n=ParentRescueStory.data(s);n.putBoolean("Started",true);n.putBoolean("KeyTaken",true);n.putBoolean("KeySwallowed",true);s.loop.story.putBoolean("LittleDoorKeyIssued",true);s.loop.story.putString("LittleDoorKeyHolder","EVIL_OTHER_MOTHER");return p;}
    @GameTest(template="empty") public static void legacyReplacementIsBoundPersistedAndIssuedOnlyOnce(GameTestHelper helper){
        var p=player(helper);var s=OtherMotherLoop.scene(p);
        try{helper.assertTrue(StoryItemCustody.recoverSwallowedKey(p,s),"Eligible legacy save remained blocked");var replacement=StoryItemCustody.held(s,"Key");helper.assertTrue(ParentRescueStory.key(replacement,s)&&replacement.getTag().getBoolean("LegacyReplacement"),"Replacement lost its binding or truthful provenance");var receipt=replacement.getTag().getUUID("LegacyReplacementReceipt");
            s.loop=OtherMotherLoopState.load(s.loop.save());helper.assertTrue(StoryItemCustody.recoverSwallowedKey(p,s)&&StoryItemCustody.held(s,"Key").getTag().getUUID("LegacyReplacementReceipt").equals(receipt),"Reload issued a fresh replacement");
            helper.assertTrue(StoryItemCustody.giveBack(p,s,"Key")&&StoryItemCustody.giveBack(p,s,"Key"),"Return is not idempotent");int count=0;for(var item:p.getInventory().items)if(ParentRescueStory.key(item,s))count+=item.getCount();helper.assertTrue(count==1&&!StoryItemCustody.recoverSwallowedKey(p,s),"Returned key was duplicated");
            ParentRescueStory.data(s).getCompound("Custody").remove("Key");helper.assertFalse(StoryItemCustody.recoverSwallowedKey(p,s),"Deleting custody bypassed the independent one-time receipt");
        }finally{VisitData.get(p.server).scenes.remove(s.owner);}helper.succeed();
    }
    @GameTest(template="empty") public static void survivingOriginalWinsAndPreservesItsMetadata(GameTestHelper helper){var p=player(helper);var s=OtherMotherLoop.scene(p);try{var original=ParentRescueStory.boundKey(s);original.getOrCreateTag().putString("CustomProof","Original engraving");original.getOrCreateTag().putUUID("OriginalSerial",java.util.UUID.randomUUID());var before=original.copy();p.getEnderChestInventory().setItem(5,original);helper.assertTrue(StoryItemCustody.recoverSwallowedKey(p,s),"Surviving original was not found");helper.assertTrue(ItemStack.isSameItemSameTags(before,StoryItemCustody.held(s,"Key"))&&p.getEnderChestInventory().getItem(5).isEmpty(),"Original metadata was replaced or original left duplicated");helper.assertFalse(ParentRescueStory.data(s).hasUUID("LegacyKeyReplacementReceipt"),"A real original consumed replacement authority");}finally{VisitData.get(p.server).scenes.remove(s.owner);}helper.succeed();}
    @GameTest(template="empty") public static void foreignModernIncompleteAndDestroyedSavesCannotMintKeys(GameTestHelper helper){var p=player(helper);var foreign=player(helper);var s=OtherMotherLoop.scene(p);try{helper.assertFalse(StoryItemCustody.recoverSwallowedKey(foreign,s),"Foreign owner minted a key");var n=ParentRescueStory.data(s);n.putBoolean("KeySwallowed",false);helper.assertFalse(StoryItemCustody.recoverSwallowedKey(p,s),"Missing swallow proof minted a key");n.putBoolean("KeySwallowed",true);s.loop.story.putInt("LittleDoorKeyCustodyVersion",1);helper.assertFalse(StoryItemCustody.recoverSwallowedKey(p,s),"Modern lost key was mistaken for legacy deletion");s.loop.story.remove("LittleDoorKeyCustodyVersion");helper.assertTrue(StoryItemCustody.capture(p,s,"Key",stack->ParentRescueStory.key(stack,s))==false,"Empty inventory fabricated original custody");helper.assertTrue(StoryItemCustody.recoverSwallowedKey(p,s),"Eligible legacy recovery failed");StoryItemCustody.destroy(s,"Key");helper.assertFalse(StoryItemCustody.recoverSwallowedKey(p,s),"Destroyed receipt minted another key");}finally{VisitData.get(p.server).scenes.remove(s.owner);VisitData.get(p.server).scenes.remove(foreign.getUUID());}helper.succeed();}
    private RescueKeyMigrationGameTests(){}
}
